def reduce_if_selected(path,raw):
 raw=media_delta.reduce_if_selected(path,raw)
 if path not in SOURCE_INPUTS:return raw
 if type(raw)is not bytes:raise ValueError('lifecycle source bytes required')
 if hashlib.sha256(raw).hexdigest()!=SOURCE_INPUTS[path]:return raw
 for added,removed in EDITS[path]:
  if raw.count(added)!=1:raise ValueError('lifecycle inverse changed')
  raw=raw.replace(added,removed,1)
 if hashlib.sha256(raw).hexdigest()!=BASE_PINS[path]:raise ValueError('lifecycle baseline changed')
 return raw

def reduce_current(path,raw):
 raw=media_delta.reduce_if_selected(path,raw)
 if path not in SOURCE_INPUTS or type(raw)is not bytes or hashlib.sha256(raw).hexdigest()!=SOURCE_INPUTS[path]:raise ValueError('unreviewed lifecycle source')
 return reduce_if_selected(path,raw)

def assert_cohort(root,reader):
 from pathlib import Path
 observed={p:hashlib.sha256(reader(Path(root)/p)).hexdigest()for p in PRODUCTION_PATHS}
 if observed not in [{p:SOURCE_INPUTS[p]for p in PRODUCTION_PATHS},{p:BASE_PINS[p]for p in PRODUCTION_PATHS}]:raise ValueError('mixed or unknown lifecycle source cohort')
 return observed=={p:SOURCE_INPUTS[p]for p in PRODUCTION_PATHS}
